const icon=(n,cls='')=>`<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.braces}"/></svg>`;
const key='abap-workbench-v1';
function readState(){try{const d=JSON.parse(localStorage.getItem(key)||'{}');return d&&typeof d==='object'?d:{}}catch{return {}}}
const saved=readState();
const pageFromHash=()=>{const route=location.hash.slice(1).split('/')[0];if(route==='library')return 'docs';return ['work','docs','reference','rap','github','events','recipes','templates','quick','notes','syntax','generator','favorites','clipboard','guides','sources','settings','custom'].includes(route)?route:'work';};
const state={page:pageFromHash(),category:'전체',query:'',view:'grid',sort:'recommended',favorites:Array.isArray(saved.favorites)?saved.favorites:[],custom:Array.isArray(saved.custom)?saved.custom:[],history:Array.isArray(saved.history)?saved.history:[],checks:saved.checks||{},profile:{objectPrefix:'gcl_',split:true,...saved.profile},genKind:'alv',genOpts:{...defaults,...saved.profile},files:[],fileIndex:0,guide:'alv'};
let references=[],activeTemplate=null,modalTab='code',modalFile=0,returnFocus=null,toastTimer;
function persist(){try{localStorage.setItem(key,JSON.stringify({favorites:state.favorites,custom:state.custom,history:state.history,checks:state.checks,profile:state.profile}));}catch{toast('저장 공간이 부족하거나 브라우저 저장이 제한되어 있어요. 백업을 내려받으세요.');}}
const all=()=>[...templates,...state.custom];
const get=id=>all().find(t=>t.id===id);
const tag=(x,cls='')=>`<span class="tag ${cls}">${esc(x)}</span>`;
const external=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('upRight')}</a>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}

const navs=[['work','braces','필드 코드 만들기'],['docs','search','코드 찾기'],['reference','folder','기존 문서·원본 자료'],['rap','layers','RAP 개발 순서'],['github','github','GitHub 프로젝트'],['events','workflow','클릭·입력 이벤트'],['recipes','braces','전체 코드 따라하기'],['templates','grid','템플릿 라이브러리'],['quick','search','필드·T-code 찾기'],['notes','book','실무 노트'],['syntax','spark','구문법 ↔ 신문법'],['generator','braces','코드 생성기'],['favorites','star','즐겨찾기'],['clipboard','copy','클립보드'],['guides','book','시작부터 끝까지'],['sources','link','참고 자료']];
const primaryPages=['work','docs','rap','favorites'];
const navButton=([id,i,label])=>`<button data-nav="${id}" class="nav-item">${icon(i)}<span>${label}</span>${id==='favorites'?'<span id="favorite-count" class="nav-count"></span>':''}</button>`;
function shell(){
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#work" data-nav="work"><span class="brand-icon">${icon('braces')}</span><span>ABAP<span class="brand-small">WORKBENCH</span></span><span class="brand-dot"></span></a>
 <div class="workspace-select"><div>도현의 ABAP 자료실<small>Notion · GitHub 원문</small></div></div>
 <nav class="primary-nav">${primaryPages.map(id=>navButton(navs.find(n=>n[0]===id))).join('')}</nav><details class="sidebar-more"><summary>원본·추가 도구</summary><nav>${navs.filter(n=>!primaryPages.includes(n[0])).map(navButton).join('')}</nav></details>
 <div class="nav-caption collection-caption">MY COLLECTIONS</div><button class="nav-item collection-nav" data-category="ALV"><i class="collection-dot olive"></i><span>Classic ABAP</span><small>GUI</small></button><button class="nav-item collection-nav" data-category="RAP"><i class="collection-dot purple"></i><span>RAP & Fiori</span><small>ADT</small></button><button class="nav-item collection-nav" data-nav="custom"><i class="collection-dot orange"></i><span>내가 만든 템플릿</span><small id="custom-count"></small></button>
 <div class="sidebar-bottom"><div class="style-card"><span class="status-dot"></span> 내 코드 스타일 적용 중<p>익숙한 이름, 익숙한 구조.<br>내 방식으로 바로 시작하세요.</p><button data-nav="settings">스타일 설정 ${icon('arrow')}</button></div><button class="profile-row" data-nav="settings"><span class="avatar">D</span><span>도현의 워크벤치<small>개인용 · 브라우저에 저장</small></span>${icon('settings')}</button></div></aside>
 <div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="메뉴 열기">${icon('menu')}</button><span>Workspace</span><span class="breadcrumb-divider">/</span><strong id="breadcrumb-title">템플릿 라이브러리</strong></div><div class="topbar-right">${searchButton()}${readingControls()}<span class="local-indicator"><i></i> Personal</span><span class="top-avatar">D</span></div></header>
 <main id="main"></main><button class="back-to-top" data-to-top aria-label="맨 위로 이동">↑ 맨 위로</button><footer class="footer"><span><i class="status-dot"></i> ABAP 자료실</span><span>ABAP WORKBENCH <span class="footer-dot">·</span> 2026.10</span></footer></div>`;
 render();
}
function navigate(page,detail=''){if(page==='library')page='docs';history.pushState(null,'','#'+page+(detail?'/'+detail.split('/').map(encodeURIComponent).join('/'):''));if(page==='syntax'&&detail)selectSyntax(detail);state.page=page;state.query='';state.category='전체';$('.sidebar').classList.remove('mobile-open');closeDialog();render();window.scrollTo({top:0});}
function render(){
 document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===state.page));
 $('#favorite-count').textContent=state.favorites.length||'';$('#custom-count').textContent=state.custom.length||'';
 const title=navs.find(n=>n[0]===state.page)?.[2]||({custom:'내가 만든 템플릿',settings:'내 코드 스타일'}[state.page]);
 $('#breadcrumb-title').textContent=title;
 const pages={work:builderPage,rap:hubPage,github:hubPage,docs:()=>isRoleRoute()?rolePage():archivePage(),reference:archivePage,events:archivePage,recipes:archivePage,templates:libraryPage,favorites:libraryPage,custom:libraryPage,generator:generatorPage,clipboard:clipboardPage,guides:guidesPage,sources:sourcesPage,settings:settingsPage,syntax:syntaxPage,notes:notesPage,quick:quickPage};
 $('#main').innerHTML=(state.page==='favorites'?savedDocumentsPanel():'')+(pages[state.page]||archivePage)();
 if(state.page==='work')renderBuilder();
 if(!primaryPages.includes(state.page))$('.sidebar-more').open=true;
 if(state.page==='favorites')renderSavedDocuments();
 if(['rap','github'].includes(state.page))renderHub();
 if(['templates','favorites','custom'].includes(state.page))renderLibraryResults();
 if(state.page==='docs'&&isRoleRoute())renderRoleLibrary();else if(['docs','reference','events','recipes'].includes(state.page))renderArchive();
 if(state.page==='quick')renderQuick();
 if(state.page==='notes')renderNotes();
 if(state.page==='syntax')renderSyntax(highlight);
 if(state.page==='generator')renderEditor();
 
 if(state.page==='clipboard')renderHistory();
}
const pageHead=(eyebrow,title,desc,action='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const searchbar=(placeholder='무엇을 만들고 있나요?  ALV, F4, 조회조건…')=>`<div class="searchbox">${icon('search')}<input id="search" aria-label="템플릿 및 참고 자료 검색" placeholder="${placeholder}" value="${esc(state.query)}" autocomplete="off"><button class="search-clear" data-action="clear-search" aria-label="검색어 지우기" ${state.query?'':'hidden'}>${icon('close')}</button><kbd>Ctrl K</kbd></div>`;
function libraryPage(){const normal=state.page==='templates',fav=state.page==='favorites';return `
 ${pageHead(normal?'YOUR PERSONAL CODE TOOLKIT':fav?'KEEP IT CLOSE':'MADE BY YOU',normal?'작업에 필요한 코드를 빠르게.':fav?'자주 쓰는 코드는, 가까이에.':'내 코드가 쌓이는 곳.',normal?'흩어진 ABAP · RAP 코드를 한곳에. 찾고, 만들고, 바로 가져다 쓰세요.':fav?'별표로 모아둔 템플릿을 빠르게 꺼내 쓰세요.':'코드와 명령어, 자주 쓰는 문구를 나만의 템플릿으로 저장하세요.',`<button class="button primary" data-action="new-template">${icon('plus')} 새 템플릿</button>`)}
 ${searchbar()}
 ${normal?homeWorkPanel():''}
 ${normal?'<button class="syntax-home-banner" data-nav="syntax"><span class="tag">NEW · 18개 비교</span><strong>READ TABLE부터 FOR IN까지, 구문법 ↔ 신문법</strong><span>D2Coding으로 나란히 읽고, 바로 복사하기 →</span></button>':''}
 ${normal?`<div class="search-hints"><span>이렇게 찾아보세요</span>${['ALV 조회','F4','RAP CRUD','저장'].map(q=>`<button data-query="${q}">${q}</button>`).join('')}<span class="search-hint-end">코드 · 태그 · 내 Notion 문서 검색</span></div>
 <div class="feature-row"><button class="feature-card feature-generator" data-nav="generator"><div><span class="feature-kicker">LESS REPETITION, MORE BUILDING</span><h2>반복 코드는 맡겨두세요.</h2><p>프로그램 이름만 바꾸면, 내 스타일로 준비 끝.</p><span class="feature-link">코드 생성기 열기 ${icon('arrow')}</span></div><div class="mini-code" aria-hidden="true"><div><i></i><i></i><i></i><span>my_next_program.abap</span></div><code><b>REPORT</b> z_my_next.<br><br><b>PERFORM</b> get_data.<br><b>PERFORM</b> display_list.<span class="code-cursor"></span></code><span class="mini-badge">${icon('check')} My style</span></div></button>
 <button class="feature-card feature-guide" data-nav="guides"><span class="guide-orbit">${icon('book')}</span><span class="feature-kicker">FROM ZERO TO RUNNING</span><h2>어디에 붙이는지도, 함께.</h2><p>객체 생성부터 실행까지<br>한 단계씩 따라가는 실무 가이드.</p><span class="feature-link">처음부터 따라하기 ${icon('arrow')}</span></button></div>`:''}
 <div class="section-bar"><h2>${normal?'템플릿 라이브러리':fav?'즐겨찾는 템플릿':'나의 템플릿'} <span id="result-count"></span></h2><div class="view-controls"><select id="sort" aria-label="템플릿 정렬"><option value="recommended">추천순</option><option value="name" ${state.sort==='name'?'selected':''}>이름순</option><option value="category" ${state.sort==='category'?'selected':''}>분류순</option></select><span class="vertical-rule"></span><button class="icon-button ${state.view==='grid'?'selected':''}" data-view="grid" aria-label="그리드 보기">${icon('grid')}</button><button class="icon-button ${state.view==='list'?'selected':''}" data-view="list" aria-label="목록 보기">${icon('menu')}</button></div></div>
 <div class="filter-row">${['전체','ALV','RAP','BDC','F4 Help','SQL','유틸리티'].map(cat=>`<button class="filter ${state.category===cat?'active':''}" data-filter="${cat}">${cat==='전체'?icon('grid'):''}${cat}</button>`).join('')}<span class="filter-note">내 코드 스타일 기반 ${icon('check')}</span></div><div id="library-results"></div>
 ${normal?`<div class="reference-banner"><span class="reference-mark">${icon('link')}</span><div><strong>내가 쌓아온 자료에서 시작했어요.</strong><p>ABAP · RAP Notion 노트와 두 개의 GitHub 저장소를 바탕으로 구성했어요.</p></div><button data-nav="sources">참고 자료 보기 ${icon('upRight')}</button></div>`:''}`;}
function matches(t,q){const text=[t.title,t.description,t.category,...(t.tags||[]),...(t.files||[]).map(f=>f.code)].join(' ').toLowerCase();return q.trim().toLowerCase().split(/\s+/).every(w=>text.includes(w));}
function renderLibraryResults(){
 $('#main').classList.toggle('searching',state.page==='templates'&&!!state.query.trim());
 const relatedMatches=state.page==='templates'&&state.query.trim()&&(searchNotes(state.query).length||searchSyntax(state.query).length||searchQuick(state.query).length);
 let items=all().filter(t=>state.page!=='favorites'||state.favorites.includes(t.id)).filter(t=>state.page!=='custom'||t.custom).filter(t=>state.category==='전체'||t.category===state.category).filter(t=>matches(t,state.query));
 if(state.sort!=='recommended')items.sort((a,b)=>(state.sort==='name'?a.title:a.category).localeCompare(state.sort==='name'?b.title:b.category,'ko'));
 $('#result-count').textContent=items.length;
 const refs=state.page==='templates'&&state.query.trim()?referenceMatches().filter(r=>state.category==='전체'||(state.category==='RAP'?r.category==='RAP':r.category==='ABAP')):[];
 $('#library-results').innerHTML=(items.length?`<div class="template-grid ${state.view==='list'?'list-view':''}">${items.map(card).join('')}</div>`:relatedMatches?'':empty('아직 찾는 템플릿이 없어요.',state.query?'다른 키워드로 검색하거나 새 템플릿으로 직접 추가해보세요.':state.page==='favorites'?'템플릿의 별표를 누르면 여기에 모입니다.':'새 템플릿을 눌러 자주 쓰는 코드를 저장해보세요.'))+(state.page==='templates'&&state.query.trim()&&searchQuick(state.query).length?`<section class="syntax-search-results"><h3>필드·T-code 빠른참조</h3>${searchQuick(state.query).slice(0,6).map(r=>`<button data-quick-open="${r.id}"><span><strong>${esc(r.code)} · ${esc(r.title)}</strong><small>${esc(r.description)}</small></span><span>참조 보기 →</span></button>`).join('')}</section>`:'')+(state.page==='templates'&&state.query.trim()&&searchNotes(state.query).length?`<section class="syntax-search-results"><h3>실무 노트에서 찾기</h3>${searchNotes(state.query).slice(0,8).map(n=>`<button data-note-open="${n.id}"><span><strong>${esc(n.title)}</strong><small>${esc(n.summary)}</small></span><span>노트 보기 →</span></button>`).join('')}</section>`:'')+(state.query.trim()&&searchSyntax(state.query).length?`<section class="syntax-search-results"><h3>구문법 ↔ 신문법에서 찾기</h3>${searchSyntax(state.query).map(t=>`<button data-syntax-jump="${t.id}">${esc(t.title)} <span>비교 보기 →</span></button>`).join('')}</section>`:'')+(refs.length?`<div class="reference-search"><h3>내 Notion에서 찾은 문서 <span class="muted">${refs.length}</span></h3>${refs.slice(0,12).map(referenceRow).join('')}${refs.length>12?'<button class="button secondary" data-action="all-references">참고 자료에서 전체 결과 보기</button>':''}</div>`:'');
}
function card(t){const favorite=state.favorites.includes(t.id);return `<article class="template-card" data-card="${esc(t.id)}"><div class="card-top"><span class="template-icon ${t.category==='RAP'?'lavender':t.category==='BDC'?'sand':t.category==='F4 Help'?'blue':''}">${icon(t.icon||'braces')}</span><span class="card-type">${esc(t.label||t.category)}</span><button class="favorite icon-button ${favorite?'is-favorite':''}" data-favorite="${esc(t.id)}" aria-label="${esc(t.title)} 즐겨찾기 ${favorite?'해제':'추가'}" aria-pressed="${favorite}">${icon('star')}</button></div><h3><button data-open="${esc(t.id)}">${esc(t.title)}</button></h3><p>${esc(t.description)}</p><div class="tags">${(t.tags||[]).slice(0,3).map(x=>tag(x)).join('')}</div><div class="card-bottom"><span>${icon(t.kind?'braces':'copy')}${esc(t.level||'내 코드')}</span><button data-open="${esc(t.id)}">${t.kind?'만들기':'코드 보기'} ${icon('arrow')}</button></div></article>`;}
function empty(title,desc){return `<div class="empty-state">${icon('folder')}<h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`;}
function generatorPage(){
 if(!state.files.length)state.files=generateForEditor(state.genKind,state.genOpts);
 const rap=state.genKind==='rap',bdc=state.genKind==='bdc';
 return `${pageHead('BUILD IT YOUR WAY','내 스타일로, 바로 생성.','필요한 값만 입력하세요. 코드와 적용 순서를 함께 준비해드릴게요.')}
 <div class="generator-layout"><form id="generator-form" class="config-panel"><div class="panel-title">${icon('sliders')} 생성 옵션 <span>01</span></div>${generatorPickerHTML(state.genKind)}
 ${rap?`<label>엔티티 이름<input name="entity" value="${esc(state.genOpts.entity)}" maxlength="13" required><small>예: Travel, Student, Purchase</small></label><label>네임스페이스<select name="prefix"><option>Z</option><option ${state.genOpts.prefix==='Y'?'selected':''}>Y</option></select></label><label>구현 방식<select name="mode"><option value="managed" ${state.genOpts.mode==='managed'?'selected':''}>Managed CRUD · 비 Draft API</option><option value="readonly" ${state.genOpts.mode==='readonly'?'selected':''}>읽기 전용 · Fiori 조회</option></select></label>`:`<label>프로그램 이름<input name="program" value="${esc(state.genOpts.program)}" maxlength="34" required spellcheck="false"><small>Z 또는 Y로 시작하는 프로그램명</small></label>${!bdc&&(state.genKind==='fcat-ddic'||['alv','f4','sql','salv','f4-dynpro','make-fcat','alv-toolbar','alv-top-event','alv-edit','alv-hotspot','crud','db-create','db-update','db-delete','range'].includes(state.genKind))?`<div class="form-pair"><label>DDIC 테이블<input name="table" value="${esc(state.genOpts.table)}" maxlength="16" required></label><label>조회 키 필드<input name="key" value="${esc(state.genOpts.key)}" maxlength="30" required></label></div>`:''}${(state.genKind==='alv'||state.genKind.startsWith('f4-')||(state.genKind.startsWith('fcat-')||['alv-newko','make-fcat','alv-toolbar','alv-top','alv-top-event','alv-edit','alv-hotspot'].includes(state.genKind)))?`<label>화면 번호<input name="screen" value="${esc(state.genOpts.screen)}" maxlength="4" pattern="[0-9]{4}" required></label>${state.genKind==='alv'?`<label class="check-label"><input type="checkbox" name="split" ${state.genOpts.split?'checked':''}><span>Include 파일로 분리<small>TOP / S01 / O01 / I01 / F01</small></span></label>`:''}`:''}`}
 <label>객체 참조 접두사<select name="objectPrefix"><option value="gcl_" ${state.genOpts.objectPrefix==='gcl_'?'selected':''}>GCL_ · FORM/PERFORM</option><option value="go_" ${state.genOpts.objectPrefix==='go_'?'selected':''}>GO_ · FORM/PERFORM</option></select></label>${state.genKind.startsWith('f4-')?`<label>Dynpro 반환 필드<input placeholder="GV_ACCOUNT 또는 GS_INPUT-ACCOUNT" name="screenField" value="${esc(state.genOpts.screenField||'GV_VALUE')}" maxlength="61"></label>`:''}${(state.genKind.startsWith('fcat-')||['alv-newko','make-fcat','alv-toolbar','alv-top','alv-top-event','alv-edit','alv-hotspot'].includes(state.genKind))?`<label>Custom Container 이름<input name="container" value="${esc(state.genOpts.container||'CC_ALV')}" maxlength="30"></label>`:''}<div class="applied-style"><span class="status-dot"></span><div>도현의 코드 스타일<small>${state.genOpts.objectPrefix} · DATA / LIKE · FORM / PERFORM</small></div></div><div id="gen-errors" role="alert"></div><button class="button primary generate-button" type="submit">${icon('spark')} 코드 생성하기 ${icon('arrow')}</button><p class="form-hint">템플릿의 변수를 치환해 생성합니다.<br>SAP 시스템에서 문법 검사 후 적용하세요.</p></form>
 <section class="editor-panel"><div class="editor-panel-title"><div>${icon('braces')} 생성된 코드 <span id="file-count"></span></div><div class="editor-actions"><button class="button small ghost" data-action="copy-all-generated">전체 구역 복사</button><button class="button small ghost" data-action="download-all">${icon('download')} 전체 HTML ZIP</button><button class="button small dark" data-action="copy-generated">${icon('copy')} 현재 파일 복사</button></div></div><div id="generated-editor"></div></section></div><div class="generator-guide"><div>${icon('book')}<div><strong>붙여 넣고 나서, 무엇을 해야 하죠?</strong><p>생성할 객체와 활성화 순서를 가이드에서 확인하세요.</p></div></div><button class="button secondary" ${guides[state.genKind]?`data-guide="${state.genKind}"`:'data-action="generated-readme"'}>생성물 적용 안내 ${icon('arrow')}</button></div>`;
}
function highlight(code){return highlightCode(code);}
function editorMarkup(files,index,context){const f=files[index]||files[0];return `<div class="file-tabs" role="tablist" aria-label="코드 파일">${files.map((f,i)=>`<button role="tab" aria-selected="${index===i}" class="${index===i?'active':''}" data-${context}-file="${i}">${icon('braces')}${esc(f.name)}</button>`).join('')}</div><div class="code-location"><span>${icon('folder')} ${esc(f.where)}</span><button data-action="${context==='gen'?'download-current':'download-modal'}" ${!isCodeFile(f)?'disabled':''}>${icon('download')} ${isCodeFile(f)?'HTML 저장':'설정 안내 · 저장 제외'}</button></div><pre class="code-view ${f.name.endsWith('.txt')?'plain-code':''}" tabindex="0" aria-label="${esc(f.name)} 코드"><code>${f.name.endsWith('.txt')?esc(f.code):highlight(f.code)}</code></pre><div class="editor-status"><span><i class="status-dot"></i> ${f.name.endsWith('.txt')?'TEXT':'ABAP'} <span>UTF-8</span></span><span>${f.code.split('\n').length} lines <span>·</span> SAP 실행 미검증</span></div>`;}
function renderEditor(){if(!$('#generated-editor'))return;state.fileIndex=Math.min(state.fileIndex,state.files.length-1);$('#generated-editor').innerHTML=editorMarkup(state.files,state.fileIndex,'gen');$('#file-count').textContent=state.files.length+' files';}
function generateForEditor(kind,opts){
 const generated=generate(kind,opts);if(kind==='rap')return generated;
 return [{name:String(opts.program||defaults.program).toLowerCase()+'_core.abap',where:'핵심 코드 · 조회조건·전역 선언은 TOP 확인',code:coreCode({id:kind,kind},generated),core:true},...generated];
}
function guidesPage(){const g=guides[state.guide]||guides.alv;return `${pageHead('FROM ZERO TO RUNNING','처음부터 실행까지, 한 걸음씩.','코드만으로 부족했던 부분까지. 만들 위치와 실행 순서를 이어드립니다.')}
 <div class="guide-layout"><aside class="guide-nav">${Object.entries(guides).map(([id,g],i)=>`<button class="${state.guide===id?'active':''}" data-guide-select="${id}"><span>0${i+1}</span><div>${g.title.split(',')[0]}<small>${g.steps.length}단계 가이드</small></div>${icon('arrow')}</button>`).join('')}<div class="guide-aside-note">${icon('book')}<p>직접 확인한 단계에 체크하세요.<br>진행 상황은 이 브라우저에 저장됩니다.</p></div></aside><section class="guide-content"><div class="guide-title"><span class="eyebrow">${state.guide.toUpperCase()} DEVELOPMENT GUIDE</span><h2>${g.title}</h2><p>${g.subtitle}</p><div class="progress-track"><i style="width:${progress(state.guide)}%"></i></div><small>${g.steps.filter((_,i)=>state.checks[state.guide+':'+i]).length} / ${g.steps.length} 완료</small></div><div class="steps">${g.steps.map(([title,desc],i)=>`<label class="step ${state.checks[state.guide+':'+i]?'done':''}"><input type="checkbox" data-step="${state.guide}:${i}" ${state.checks[state.guide+':'+i]?'checked':''}><span class="step-number">${state.checks[state.guide+':'+i]?icon('check'):String(i+1).padStart(2,'0')}</span><span><strong>${title}</strong><p>${desc}</p></span></label>`).join('')}</div><div class="guide-bottom"><button class="button primary" data-generate-kind="${state.guide}">${icon('braces')} 이 코드 생성하기</button>${external(sources[state.guide][0].url,'원본 노트 보기','text-link')}</div><p class="footnote">코드와 가이드는 참고 자료를 바탕으로 재구성했습니다. SAP에서 컴파일·실행한 결과는 아닙니다.</p></section></div>`;}
function progress(id){const g=guides[id];return g.steps.filter((_,i)=>state.checks[id+':'+i]).length/g.steps.length*100;}
function referenceMatches(){return references.filter(r=>state.query.toLowerCase().trim().split(/\s+/).every(q=>(r.title+' '+r.category).toLowerCase().includes(q)));}
function referenceRow(r){return `<a class="reference-row" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><span class="reference-n">N</span><div><strong>${esc(r.title)}</strong><small>${esc(r.category)} · Notion 원문</small></div>${icon('upRight')}</a>`;}
function sourcesPage(){return `${pageHead('SOURCE / COVERAGE','내 노션·GitHub 원문과 확인 내역','본문·코드·화면 캡처를 사이트 안에서 읽고 검색합니다. 원본 링크와 수집 범위도 함께 남겼습니다.')}<div class="source-grid">${collections.map(c=>`<a class="source-card" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer"><span class="source-logo">${c.type==='Notion'?'N':icon('github')}</span><span class="source-type">${esc(c.type)} ${icon('upRight')}</span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><span class="source-verified">${icon('check')} 원문 연결</span></a>`).join('')}</div><section class="settings-card"><h2>2026.10.18 원문 대조</h2><p>Notion ${coverage.notion||517}개 문서, 두 GitHub 저장소 원본 ${coverage.github||1375}개 파일을 수록했습니다. RAP 하위 96개와 ABAP 루트 203개 연결을 대조했고, 접근할 수 없는 외부 Notion 3개는 원문 링크를 유지했습니다.</p><p>노션 캡처는 본문에서 열 수 있습니다. 이미지 안의 글자는 검색하지 않으며, 원문 변경은 자동 동기화하지 않습니다. SAP에서의 컴파일·실행은 별도 확인이 필요합니다.</p><div class="backup-buttons"><button class="button primary" data-nav="docs">기능별 본문·코드 찾기</button><button class="button secondary" data-nav="rap">RAP 개발 순서</button><button class="button secondary" data-nav="github">GitHub 원본 찾기</button></div></section>`;}

function renderReferences(){const refs=referenceMatches();$('#reference-results').innerHTML=`<div class="results-label">${refs.length}개 문서 · 제목과 분류 검색</div>`+(refs.length?refs.map(referenceRow).join(''):empty('검색 결과가 없어요.','“조회”, “ALV”, “Behavior”처럼 짧은 키워드로 검색해보세요.'));}
function clipboardPage(){return `${pageHead('COPY. KEEP. REUSE.','방금 쓴 코드도, 다음에 쓸 문구도.','이 사이트에서 복사한 코드와 직접 붙여 넣은 내용을 모아둡니다.',`<button class="button primary" data-action="paste-note">${icon('plus')} 직접 저장</button>`)}${searchbar('저장한 코드·명령어·텍스트 검색…')}<div class="clipboard-note">${icon('copy')} 복사 기록은 최근 50개까지 이 브라우저에 저장됩니다. 다른 앱의 클립보드는 자동 수집하지 않습니다.</div><div class="section-bar"><h2>나의 클립보드 <span>${state.history.length}</span></h2>${state.history.length?'<button class="text-button muted" data-action="clear-history">기록 비우기</button>':''}</div><div id="history-results"></div>`;}
function renderHistory(){const history=state.history.filter(h=>(h.title+' '+h.code).toLowerCase().includes(state.query.toLowerCase()));$('#history-results').innerHTML=history.length?`<div class="history-list">${history.map(h=>`<article class="history-card"><div class="history-head"><span class="template-icon">${icon('copy')}</span><div><h3>${esc(h.title)}</h3><small>${new Date(h.time).toLocaleString('ko-KR')}</small></div><button class="button small secondary" data-history-copy="${h.id}">${icon('copy')} 다시 복사</button><button class="icon-button" data-history-delete="${h.id}" aria-label="기록 삭제">${icon('trash')}</button></div><pre>${esc(h.code.slice(0,700))}${h.code.length>700?'\n…':''}</pre></article>`).join('')}</div>`:empty('다시 쓸 코드를 여기 모아두세요.',state.query?'검색어와 일치하는 기록이 없습니다.':'템플릿을 복사하거나 직접 저장을 눌러 첫 기록을 만들어보세요.');}
function settingsPage(){return `${pageHead('FAMILIAR BY DESIGN','내 코드는, 내 방식으로.','실제 GitHub 코드에서 확인한 규칙을 기본 스타일로 적용했습니다.')}
 <div class="settings-layout"><form id="settings-form" class="settings-card"><h2>${icon('sliders')} 생성 스타일</h2><label>객체 참조 변수 접두사<select name="objectPrefix"><option value="gcl_" ${state.profile.objectPrefix==='gcl_'?'selected':''}>gcl_ · 내 저장소 스타일</option><option value="go_" ${state.profile.objectPrefix==='go_'?'selected':''}>go_ · 객체 접두사</option></select></label><label class="check-label"><input type="checkbox" name="split" ${state.profile.split?'checked':''}><span>ALV Include 분리를 기본값으로<small>TOP / S01 / O01 / I01 / F01</small></span></label><div class="convention-list"><div><span>전역 테이블 · 구조 · 값</span><code>gt_ · gs_ · gv_</code></div><div><span>지역 변수</span><code>lt_ · ls_ · lv_</code></div><div><span>Classic ABAP 흐름</span><code>FORM / PERFORM</code></div><div><span>설명 주석</span><code>한국어 + 구간 구분선</code></div></div><button class="button primary" type="submit">${icon('check')} 스타일 저장</button><p class="footnote">저장한 스타일은 이후 생성하는 코드에 적용됩니다. RAP은 CDS·Behavior 객체 구조를 따릅니다.</p></form>
 <div><section class="settings-card"><h2>${icon('download')} 내 작업 백업</h2><p>내 템플릿, 저장한 원문·최근 자료, 즐겨찾기, 복사 기록, 가이드 진행 상황과 스타일 설정을 JSON 파일로 보관하세요.</p><div class="backup-buttons"><button class="button secondary" data-action="export">${icon('download')} 백업 내보내기</button><label class="button secondary import-label">${icon('folder')} 백업 가져오기<input type="file" id="import-file" accept="application/json,.json" hidden></label></div><p class="footnote">가져오기는 기존 항목을 유지하면서 병합합니다. 이 브라우저의 데이터는 다른 기기와 자동 동기화하지 않습니다.</p></section><section class="settings-card provenance"><h2>${icon('github')} 코드 스타일의 출처</h2><p>ABAP-STUDY의 ALV 코드와 Masterpack FI의 FORM·F4 구현을 확인했습니다. 원본 업무 테이블은 예제용 SCARR 또는 직접 입력한 이름으로 바꾸어 생성합니다.</p>${collections.filter(x=>x.type==='GitHub').map(c=>external(c.url,c.name,'text-link')).join('')}</section></div></div>`;}

function openDialog(html,cls=''){returnFocus=document.activeElement;$('#overlay').innerHTML=`<dialog class="dialog ${cls}" aria-label="${cls==='template-dialog'?'템플릿 상세':'입력 창'}">${html}</dialog>`;const d=$('dialog');d.showModal();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});d.addEventListener('cancel',()=>closeDialog());}
function closeDialog(){const d=$('dialog');if(d){d.close();$('#overlay').innerHTML='';returnFocus?.focus?.();}}
function openTemplate(id){activeTemplate=get(id);if(!activeTemplate)return;modalTab='code';modalFile=0;renderTemplateDialog();}
function fullSourcePanel(t){const names=[...new Set((t.title+' '+t.category+' '+(t.tags||[]).join(' ')).toLowerCase().split(/[^a-z0-9가-힣_]+/).filter(w=>w.length>1))];const candidates=documents.filter(d=>d.recipe&&d.source==='Notion').map(d=>({d,score:names.reduce((n,w)=>n+(d.title.toLowerCase().includes(w)?5:d.search.includes(w)?1:0),0)+((t.sources||[]).some(s=>s.url?.includes(d.id.replace('notion-','')))?100:0)})).filter(r=>r.score>0).sort((a,b)=>b.score-a.score).slice(0,12);return `<div class="modal-body complete-source-panel"><h3>노션의 전체 프로그램과 원문 주석</h3><p>아래 문서를 열면 TOP 선언·호출·클래스·MODULE·FORM과 주석을 본문에서 전부 읽고 복사할 수 있습니다. 화면 Flow Logic은 따로 복사합니다.</p>${candidates.map(({d})=>`<button class="event-related" data-doc-link="${esc(d.id)}"><small>${esc(d.category)} · 전체 코드·원문 설명</small><strong>${esc(d.title)}</strong></button>`).join('')||'<p>일치하는 전체 예제가 없습니다. 문서함에서 관련 원문을 검색하세요.</p>'}<button class="button secondary" data-nav="recipes">전체 코드 문서함 열기</button></div>`;}
function renderTemplateDialog(){const t=activeTemplate;const head=`<div class="dialog-head"><div><span class="eyebrow">${esc(t.category)} TEMPLATE</span><h2>${esc(t.title)}</h2><p>${esc(t.description)}</p></div><button class="icon-button" data-action="close" aria-label="닫기">${icon('close')}</button></div><div class="modal-tabs">${[['code','템플릿 코드'],['complete','노션 전체 코드·주석'],['guide','적용 가이드'],['source','참고 출처']].map(([id,name])=>`<button class="${modalTab===id?'active':''}" data-modal-tab="${id}">${name}</button>`).join('')}<span>${esc(t.level)}</span></div>`;
 let body;if(modalTab==='complete')body=fullSourcePanel(t);else if(modalTab==='code')body=`<div class="modal-editor">${editorMarkup(t.files,modalFile,'modal')}</div>`;else if(modalTab==='guide'){const g=guides[t.guide];body=`<div class="modal-body">${g?g.steps.map(([title,desc],i)=>`<div class="compact-step"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${title}</h3><p>${desc}</p></div></div>`).join(''):`<h3>붙여 넣을 위치</h3><p>${esc(t.files[0].where)}</p><p>스니펫의 전제 조건과 선언을 먼저 확인하고, 기존 FORM 이름과 중복되지 않도록 조정하세요. 전체 프로그램은 SE38에 새 실행 프로그램으로 생성합니다.</p>`}<p class="footnote">SAP 시스템 컴파일·실행 미검증 · 실제 DDIC와 릴리스에 맞게 확인하세요.</p></div>`;}else body=`<div class="modal-body"><h3>이 템플릿의 바탕이 된 자료</h3><p>원문의 패턴을 참고해 재사용 가능한 형태로 재구성했습니다.</p>${(t.sources||[]).map(s=>external(s.url,s.name,'source-link')).join('')||'<p>직접 저장한 개인 템플릿입니다.</p>'}</div>`;
 const foot=`<div class="dialog-foot"><span>${icon('check')} ${t.custom?'내가 저장한 코드':'내 코드 스타일 · 한국어 가이드'}</span><div>${t.custom?`<button class="button secondary" data-edit-template="${t.id}">${icon('edit')} 편집</button>`:''}<button class="button secondary" data-modal-tab="complete">노션 전체 코드·주석</button>${modalTab==='complete'?'':`<button class="button secondary" data-action="copy-modal">${icon('copy')} 현재 파일 복사</button>`}${t.kind?`<button class="button primary" data-customize="${t.id}">설정하고 생성 ${icon('arrow')}</button>`:''}</div></div>`;
 if($('dialog.template-dialog'))$('dialog').innerHTML=head+body+foot;else openDialog(head+body+foot,'template-dialog');
}
function templateForm(id){const t=id?get(id):null;openDialog(`<form id="template-form"><div class="dialog-head"><div><span class="eyebrow">MY CODE COLLECTION</span><h2>${t?'템플릿 편집':'새 템플릿 만들기'}</h2></div><button class="icon-button" data-action="close" type="button" aria-label="닫기">${icon('close')}</button></div><div class="form-body"><input type="hidden" name="templateId" value="${esc(id||'')}"><label>템플릿 이름<input name="title" value="${esc(t?.title||'')}" placeholder="예: FI 전표 조회 조건" maxlength="80" required></label><div class="form-pair"><label>분류<select name="category">${['ALV','RAP','BDC','F4 Help','SQL','유틸리티'].map(c=>`<option ${t?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>검색 태그<input name="tags" value="${esc(t?.tags?.join(', ')||'')}" placeholder="전표, FI, 조회" maxlength="150"></label></div><label>한 줄 설명<input name="description" value="${esc(t?.description||'')}" placeholder="어떤 상황에서 사용하는 코드인가요?" maxlength="200"></label><label>코드 · 명령어 · 텍스트<textarea name="code" rows="11" maxlength="200000" spellcheck="false" required placeholder="자주 쓰는 코드를 붙여 넣으세요.">${esc(t?.files?.[0]?.code||'')}</textarea></label></div><div class="dialog-foot"><span>이 브라우저에 저장됩니다</span><div>${t?`<button class="button danger" type="button" data-delete-template="${esc(id)}">삭제</button>`:''}<button class="button primary" type="submit">${icon('check')} 템플릿 저장</button></div></div></form>`,'form-dialog');}
function noteForm(){openDialog(`<form id="note-form"><div class="dialog-head"><div><span class="eyebrow">KEEP FOR LATER</span><h2>클립보드에 직접 저장</h2></div><button class="icon-button" data-action="close" type="button" aria-label="닫기">${icon('close')}</button></div><div class="form-body"><label>이름<input name="title" required maxlength="80" placeholder="예: ADT 패키지 이름"></label><label>내용<textarea name="code" required rows="10" maxlength="200000" placeholder="코드나 문구를 여기에 붙여 넣으세요."></textarea></label></div><div class="dialog-foot"><span>직접 입력한 내용만 저장합니다</span><button class="button primary" type="submit">${icon('check')} 저장</button></div></form>`,'form-dialog');}
function record(title,code){state.history=state.history.filter(h=>h.code!==code);state.history.unshift({id:crypto.randomUUID(),title,code,time:new Date().toISOString()});state.history=state.history.slice(0,50);persist();}
async function copy(code,title){try{await navigator.clipboard.writeText(code);record(title,code);toast('복사했어요. 클립보드 기록에도 저장했습니다.');}catch{const ta=document.createElement('textarea');ta.value=code;ta.style.cssText='position:fixed;left:-10000px';($('dialog')||document.body).appendChild(ta);ta.select();let ok=false;try{ok=document.execCommand('copy')}catch{}ta.remove();if(ok){record(title,code);toast('코드를 복사했습니다.');}else toast('복사가 제한되어 있어요. 코드를 선택하거나 파일로 저장해주세요.');}}
function download(name,content,type='text/plain;charset=utf-8'){if(/\.(abap|asddl|bdef|ddls)$/i.test(name)&&typeof content==='string'){content=codeOnlyHTML(name,content);name=name.replace(/\.[^.]+$/,'.html');type='text/html;charset=utf-8';}const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function zip(files){files=htmlFiles(files);const enc=new TextEncoder(),chunks=[],central=[];let offset=0;const crc=b=>{let c=0xffffffff;for(const v of b){c^=v;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;};for(const f of files){const name=enc.encode(f.name),data=enc.encode(f.code),sum=crc(data);const h=new Uint8Array(30+name.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,sum,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);h.set(name,30);chunks.push(h,data);const c=new Uint8Array(46+name.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,sum,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=h.length+data.length;}const size=central.reduce((s,c)=>s+c.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});}

document.addEventListener('click',async e=>{
 const b=e.target.closest('button,a[data-nav]');if(!b)return;
 if(b.dataset.nav){e.preventDefault();navigate(b.dataset.nav);return;}
 if(b.dataset.favorite){const id=b.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();$('#favorite-count').textContent=state.favorites.length||'';renderLibraryResults();return;}
 if(b.dataset.open){openTemplate(b.dataset.open);return;}
 if(b.dataset.category){navigate('templates');state.category=b.dataset.category;render();return;}
 if(b.dataset.filter){state.category=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderLibraryResults();return;}
 if(b.dataset.query){state.query=b.dataset.query;$('#search').value=state.query;$('.search-clear').hidden=false;renderLibraryResults();return;}
 if(b.dataset.view){state.view=b.dataset.view;render();return;}
 if(b.dataset.guide){state.guide=b.dataset.guide;navigate('guides');return;}
 if(b.dataset.guideSelect){state.guide=b.dataset.guideSelect;render();return;}
 if(b.dataset.generateKind){state.genKind=b.dataset.generateKind;state.genOpts={...defaults,...state.profile};state.files=[];navigate('generator');return;}
 if(b.dataset.customize){const t=get(b.dataset.customize);state.genKind=t.kind;state.genOpts={...defaults,...state.profile,...t.options,program:{f4:'ZF4_SCARR',bdc:'ZBDC_TEMPLATE',sql:'ZSQL_SCARR',alv:'ZALV_SCARR'}[t.kind]||defaults.program};state.files=[];state.fileIndex=0;navigate('generator');return;}
 if(b.dataset.genFile!==undefined){state.fileIndex=Number(b.dataset.genFile);renderEditor();return;}
 if(b.dataset.modalFile!==undefined){modalFile=Number(b.dataset.modalFile);renderTemplateDialog();return;}
 if(b.dataset.modalTab){modalTab=b.dataset.modalTab;renderTemplateDialog();return;}
 if(b.dataset.editTemplate){templateForm(b.dataset.editTemplate);return;}
 if(b.dataset.deleteTemplate){if(confirm('이 템플릿을 삭제할까요?')){state.custom=state.custom.filter(t=>t.id!==b.dataset.deleteTemplate);state.favorites=state.favorites.filter(id=>id!==b.dataset.deleteTemplate);persist();closeDialog();render();toast('템플릿을 삭제했습니다.');}return;}
 if(b.dataset.historyCopy){const h=state.history.find(h=>h.id===b.dataset.historyCopy);if(h)await copy(h.code,h.title);renderHistory();return;}
 if(b.dataset.historyDelete){state.history=state.history.filter(h=>h.id!==b.dataset.historyDelete);persist();render();return;}
 const action=b.dataset.action;
 if(action==='menu')$('.sidebar').classList.toggle('mobile-open');
 if(action==='new-template')templateForm();
 if(action==='close')closeDialog();
 if(action==='paste-note')noteForm();
 if(action==='clear-search'){state.query='';$('#search').value='';$('.search-clear').hidden=true;refreshSearch();$('#search').focus();}
 if(action==='all-references'){const q=state.query;navigate('sources');state.query=q;render();}
 if(action==='generated-readme'){state.fileIndex=Math.max(0,state.files.findIndex(f=>f.name.endsWith('.txt')));renderEditor();$('#generated-editor').scrollIntoView({block:'start'});}
 if(action==='copy-all-generated'){await copy(state.files.filter(f=>isCodeFile(f)&&!f.core).map(f=>'* ===== '+f.name+' · '+f.where+' =====\n'+f.code).join('\n\n'),'전체 생성 코드');}
 if(action==='copy-generated'){const f=state.files[state.fileIndex];await copy(f.code,f.name);}
 if(action==='copy-modal'){const f=activeTemplate.files[modalFile];await copy(f.code,activeTemplate.title+' · '+f.name);}
 if(action==='download-current'){const f=state.files[state.fileIndex];download(f.name,f.code);}
 if(action==='download-modal'){const f=activeTemplate.files[modalFile];download(f.name,f.code);}
 if(action==='download-all'){download('abap-workbench-'+state.genKind+'.zip',zip(state.files),'application/zip');toast('생성된 파일을 ZIP으로 내려받습니다.');}
 if(action==='clear-history'&&confirm('복사 기록을 모두 비울까요?')){state.history=[];persist();render();}
 if(action==='export'){download('abap-workbench-backup.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),favorites:state.favorites,custom:state.custom,history:state.history,checks:state.checks,profile:state.profile,workNotes:exportNotesState(),documents:exportDocuments()},null,2),'application/json');toast('내 작업 백업을 내려받습니다.');}
});
function refreshSearch(){if(state.page==='clipboard')renderHistory();else renderLibraryResults();}
document.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;$('.search-clear').hidden=!state.query;refreshSearch();}else if(e.target.id!=='generator-search'&&e.target.closest('#generator-form')){const ed=$('.editor-panel');ed?.classList.add('stale');$('#gen-errors').textContent='옵션이 바뀌었어요. 코드 생성하기를 눌러 반영하세요.';}});
document.addEventListener('change',async e=>{
 if(e.target.id==='sort'){state.sort=e.target.value;renderLibraryResults();}
 if(e.target.id==='generator-major'||e.target.id==='generator-middle'){const pick=generatorPicker(state.genKind);const major=e.target.id==='generator-major'?e.target.value:pick.selected.major;const middle=e.target.id==='generator-middle'?e.target.value:null;const entry=generatorEntries.find(r=>r.major===major&&(!middle||r.middle===middle));if(entry){selectGenerator(entry.kind);}return;}
 if(e.target.id==='generator-kind'){const previous=Object.fromEntries(new FormData(e.target.form));state.genKind=e.target.value;state.genOpts={...defaults,...state.profile,...(['crud','db-create','db-update','db-delete'].includes(state.genKind)?{table:'ZWB_DEMO',key:'ID'}:{}),program:{alv:'ZALV_SCARR',f4:'ZF4_SCARR',bdc:'ZBDC_TEMPLATE',sql:'ZSQL_SCARR'}[state.genKind]||defaults.program};state.genOpts={...state.genOpts,...Object.fromEntries(Object.entries(previous).filter(([key])=>['program','screen','screenField','container','objectPrefix'].includes(key)))};state.files=[];state.fileIndex=0;render();}
 if(e.target.dataset.step){state.checks[e.target.dataset.step]=e.target.checked;persist();const y=window.scrollY;render();window.scrollTo({top:y});}
 if(e.target.id==='import-file'&&e.target.files[0]){try{if(e.target.files[0].size>8_000_000)throw Error('백업 파일은 8MB 이하만 가져올 수 있어요.');const d=JSON.parse(await e.target.files[0].text());if(d.version!==1||!Array.isArray(d.custom)||!Array.isArray(d.history)||!Array.isArray(d.favorites))throw Error('지원하는 Workbench 백업 형식이 아닙니다.');
 const custom=d.custom.map(t=>{if(!t||typeof t.id!=='string'||!/^custom-[A-Za-z0-9_-]{1,80}$/.test(t.id)||typeof t.title!=='string'||!Array.isArray(t.files)||!t.files.length||typeof t.files[0]?.code!=='string'||!['ALV','RAP','BDC','F4 Help','SQL','유틸리티'].includes(t.category))throw Error('템플릿 데이터가 올바르지 않습니다.');return {id:t.id,title:t.title.slice(0,80),description:String(t.description||'').slice(0,200),category:t.category,label:t.category,custom:true,icon:'braces',level:'내 코드',tags:Array.isArray(t.tags)?t.tags.filter(x=>typeof x==='string').slice(0,10):[],files:[{name:'my_snippet.abap',code:t.files[0].code.slice(0,200000),where:'직접 저장한 코드'}],sources:[]};});
 const hist=d.history.map(h=>{if(typeof h?.code!=='string'||typeof h?.title!=='string'||!Number.isFinite(Date.parse(h.time)))throw Error('클립보드 데이터가 올바르지 않습니다.');return {id:crypto.randomUUID(),title:h.title.slice(0,120),code:h.code.slice(0,200000),time:h.time};});
 state.custom=[...new Map([...custom,...state.custom].map(t=>[t.id,t])).values()];state.favorites=[...new Set([...state.favorites,...d.favorites.filter(x=>typeof x==='string')])].filter(id=>get(id));state.history=[...new Map([...state.history,...hist].map(h=>[h.code,h])).values()].sort((a,b)=>new Date(b.time)-new Date(a.time)).slice(0,50);if(d.checks&&typeof d.checks==='object')for(const [k,v] of Object.entries(d.checks))if(/^(alv|rap|f4|bdc):\d+$/.test(k)&&typeof v==='boolean'&&state.checks[k]===undefined)state.checks[k]=v;
 if(['gcl_','go_'].includes(d.profile?.objectPrefix))state.profile.objectPrefix=d.profile.objectPrefix;if(typeof d.profile?.split==='boolean')state.profile.split=d.profile.split;mergeNotesState(d.workNotes);mergeDocuments(d.documents);persist();render();toast('백업을 가져왔습니다. 기존 항목은 유지됩니다.');}catch(err){toast(err.message||'백업 파일을 읽지 못했습니다.');e.target.value='';}}
});
document.addEventListener('submit',e=>{
 if(!['generator-form','template-form','note-form','settings-form'].includes(e.target.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));
 if(e.target.id==='generator-form'){try{state.genOpts={...state.genOpts,...data,split:data.split==='on',objectPrefix:data.objectPrefix||state.profile.objectPrefix};state.files=generateForEditor(state.genKind,state.genOpts);state.fileIndex=0;render();toast('핵심 코드와 구역별 파일을 생성했습니다.');}catch(err){$('#gen-errors').textContent=err.message;}return;}
 if(e.target.id==='template-form'){if(!data.title.trim()||!data.code.trim()){toast('이름과 코드를 입력해주세요.');return;}const id=data.templateId||'custom-'+crypto.randomUUID();const t={id,custom:true,title:data.title.trim(),description:data.description.trim()||'직접 저장한 나의 코드 템플릿',category:data.category,label:data.category,tags:data.tags.split(',').map(s=>s.trim()).filter(Boolean).slice(0,6),icon:'braces',level:'내 코드',sources:[],files:[{name:'my_snippet.abap',code:data.code,where:'직접 저장한 코드'}]};state.custom=state.custom.filter(t=>t.id!==id);state.custom.unshift(t);persist();closeDialog();navigate('custom');toast('내 템플릿에 저장했습니다.');return;}
 if(e.target.id==='note-form'){if(!data.title.trim()||!data.code.trim()){toast('이름과 내용을 입력해주세요.');return;}record(data.title,data.code);closeDialog();render();toast('클립보드에 저장했습니다.');return;}
 if(e.target.id==='settings-form'){state.profile={objectPrefix:data.objectPrefix,split:data.split==='on'};persist();state.genOpts={...state.genOpts,...state.profile};state.files=[];render();toast('코드 스타일을 저장했습니다.');}
});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#search')&&!$('#syntax-search')&&!$('#notes-search')&&!$('#quick-search'))navigate('templates');const input=$('#quick-search')||$('#notes-search')||$('#syntax-search')||$('#search');input.focus();input.select();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog')){e.preventDefault();if(!$('#role-search')&&!$('#archive-search')&&!$('#hub-search'))navigate('docs');($('#role-search')||$('#archive-search')||$('#hub-search'))?.focus();return;}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&state.page==='generator'&&!$('dialog')){e.preventDefault();$('#generator-form').requestSubmit();}});

