bindWorkNotes({highlight,copy,navigate,toast});
bindQuick({navigate,copy});
bindArchive({navigate,copy,download,toast,zip});
bindCodeResults({copy});
bindBuilder({copy,download,zip});
bindHub({navigate});
shell();
bindReading({copy,toast});
bindUniversalSearch({all,references:()=>references,navigate,openTemplate});
loadArchive().catch(()=>toast('문서함 색인을 불러오지 못했습니다. 문서함에서 다시 시도해주세요.'));
window.addEventListener('hashchange',()=>{state.page=pageFromHash();state.query='';if(state.page==='syntax'&&location.hash.includes('/'))selectSyntax(location.hash.split('/')[1]);closeDialog();render();window.scrollTo({top:0});});
try{const r=await fetch('./reference-index.json');if(!r.ok)throw Error();references=await r.json();if(state.page==='sources')render();else if(state.query)refreshSearch();}catch{toast('참고 자료 색인을 불러오지 못했어요. 새로고침해주세요.');}

document.addEventListener('input',e=>{if(e.target.id==='generator-search'){const q=e.target.value.toLowerCase();const matches=q?generatorEntries.filter(r=>(r.title+' '+r.kind+' '+r.description+' '+r.middle).toLowerCase().includes(q)):[];document.querySelector('#generator-search-results').innerHTML=matches.map(r=>`<button type="button" data-picker-kind="${r.kind}">${esc(r.title)}<small>${esc(r.middle)}</small></button>`).join('');}});

function selectGenerator(kind){const form=document.querySelector('#generator-form');if(form){const prior=Object.fromEntries(new FormData(form));state.genOpts={...state.genOpts,...prior};}state.genKind=kind;if(['crud','db-create','db-update','db-delete'].includes(kind))Object.assign(state.genOpts,{table:'ZWB_DEMO',key:'ID'});state.files=[];state.fileIndex=0;navigate('generator');}
