bindRoleLibrary({navigate,copy,download,selectGenerator,buildTask(kind,ddic,table){configureBuilder(kind,ddic,table);navigate('work');},findOriginal(query){navigate('reference');const input=document.querySelector('#archive-search');if(input){input.value=query;input.dispatchEvent(new Event('input',{bubbles:true}));}}});
